import CareerApplication from './CareerApplication.jsx';
import { useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertCircle, ArrowDownRight, ArrowUpRight, Bell, CalendarDays,
  CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3, CreditCard,
  FileText, FlaskConical, LayoutDashboard, LifeBuoy, Menu, MoreHorizontal,
  Plus, Search, Settings, ShieldCheck, Stethoscope, Users, UserRound, X,
  BedDouble, HeartPulse, Pill, LogOut, ClipboardList, Syringe, ScanLine, Wallet,
  Baby, Scissors, ActivitySquare, Ambulance, Droplets, Shield, Truck, Wrench,
  BellRing, CalendarClock, UserCog, FileSearch, Heart, ClipboardCheck
} from 'lucide-react';

const initialPatients = [];
const navGroups = [
  { label: 'WORKSPACE', items: [{ name: 'Overview', icon: LayoutDashboard }, { name: 'Patients', icon: Users }, { name: 'Appointments', icon: CalendarDays }, { name: 'Doctors & Staff', icon: Stethoscope }, { name: 'Departments', icon: BedDouble }] },
  { label: 'CLINICAL CARE', items: [{ name: 'Medical Records', icon: FileText }, { name: 'Nursing & Vitals', icon: HeartPulse }, { name: 'Emergency & OPD', icon: Activity }, { name: 'Laboratory', icon: FlaskConical }, { name: 'Radiology & Imaging', icon: ScanLine }, { name: 'Prescriptions', icon: ClipboardList }, { name: 'Pharmacy', icon: Pill }] },
  { label: 'INPATIENT & SPECIALTY', items: [{ name: 'Wards & Beds', icon: BedDouble }, { name: 'Admissions & Discharges', icon: ClipboardCheck }, { name: 'Surgery & Theatre', icon: Scissors }, { name: 'ICU', icon: ActivitySquare }, { name: 'Maternity & Newborn', icon: Baby }, { name: 'Dental & Physiotherapy', icon: Heart }, { name: 'Blood Bank', icon: Droplets }, { name: 'Ambulance Services', icon: Ambulance }] },
  { label: 'FINANCE & OPERATIONS', items: [{ name: 'Billing & Payments', icon: CreditCard }, { name: 'Insurance Claims', icon: Wallet }, { name: 'Procurement & Stores', icon: Truck }, { name: 'Maintenance & Equipment', icon: Wrench }, { name: 'Staff Schedules', icon: CalendarClock }] },
  { label: 'ADMINISTRATION', items: [{ name: 'Notifications', icon: BellRing }, { name: 'Medical Documents', icon: FileSearch }, { name: 'Users & Permissions', icon: UserCog }, { name: 'Audit Logs', icon: Shield }, { name: 'Reports', icon: Activity }, { name: 'Settings', icon: Settings }] },
];
const appointments = [];
const money = (n) => new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN', maximumFractionDigits: 0 }).format(n);

function App() {
  if (window.location.pathname === '/careers' || window.location.pathname === '/careers/') return <CareerApplication />;
  const [session, setSession] = useState(() => { try { return JSON.parse(localStorage.getItem('carepoint_session') || 'null'); } catch { return null; } });
  const [active, setActive] = useState('Overview');
  const [patients, setPatients] = useState(initialPatients);
  const [appointments, setAppointments] = useState([]);
  const [dashboardStats, setDashboardStats] = useState(null);
  const [search, setSearch] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [notice, setNotice] = useState('');
  const [apiState, setApiState] = useState('checking');
  const [form, setForm] = useState({ name: '', email: '', department: 'General Medicine', doctor: 'Dr. Michael Chen' });
  const filtered = useMemo(() => patients.filter(p => `${p.name} ${p.id} ${p.department}`.toLowerCase().includes(search.toLowerCase())), [patients, search]);
  useEffect(() => {
    if (!session || session.role === 'patient') return;
    const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
    fetch(`${api}/health`).then(r => r.ok ? r.json() : Promise.reject()).then(data => setApiState(data?.data?.database === 'connected' ? 'connected' : 'offline')).catch(() => setApiState('offline'));
    const authHeaders = { Authorization: `Bearer ${session.token}` };
    fetch(`${api}/patients?limit=20`, { headers: authHeaders }).then(async r => { const body = await r.json(); if (!r.ok || !body.success) throw new Error(body.message || 'Patient request failed'); return body; }).then(result => {
      if (Array.isArray(result.data)) setPatients(result.data.map(p => ({ id: p.patientId || p._id, name: p.name, email: p.email || 'Not provided', department: p.department || 'General Medicine', doctor: p.doctor || 'Unassigned', date: p.visitDate ? new Date(p.visitDate).toISOString().slice(0, 10) : '—', status: p.status || 'Waiting', initials: (p.name || '?').split(/\s+/).slice(0,2).map(n => n[0]).join('').toUpperCase(), color: 'teal' })));
    }).catch(error => setNotice(error.message || 'Unable to load patients from the API.'));
    fetch(`${api}/appointments`, { headers: authHeaders }).then(async r => { const body = await r.json(); if (!r.ok || !body.success) throw new Error(body.message || 'Appointment request failed'); return body; }).then(result => setAppointments(Array.isArray(result.data) ? result.data : [])).catch(error => setNotice(error.message || 'Unable to load appointments from the API.'));
    fetch(`${api}/dashboard/summary`, { headers: authHeaders }).then(async r => { const body = await r.json(); if (!r.ok || !body.success) throw new Error(body.message || 'Dashboard summary request failed'); return body; }).then(body => setDashboardStats(body.data)).catch(() => setDashboardStats(null));
  }, [session]);
  const choosePage = (name) => { setActive(name); setMobileNav(false); };
  const submitPatient = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    if (!session?.token) { setNotice('Your session has expired. Please sign in again.'); return; }
    const draft = { name: form.name.trim(), email: form.email.trim(), department: form.department, doctor: form.doctor, status: 'Waiting' };
    const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
    try {
      const response = await fetch(`${api}/patients`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session.token}` },
        body: JSON.stringify(draft)
      });
      const result = await response.json();
      if (!response.ok || !result.success || !result.data) throw new Error(result.message || 'Could not save the patient.');
      const saved = result.data;
      const patient = {
        id: saved.patientId || saved._id,
        name: saved.name,
        email: saved.email || 'Not provided',
        department: saved.department || 'General Medicine',
        doctor: saved.doctor || 'Unassigned',
        date: saved.visitDate ? new Date(saved.visitDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10),
        status: saved.status || 'Waiting',
        initials: saved.name.split(/\s+/).slice(0, 2).map(part => part[0]).join('').toUpperCase(),
        color: 'teal'
      };
      setPatients(prev => [patient, ...prev.filter(item => item.id !== patient.id)]);
      setApiState('connected');
      setForm({ name: '', email: '', department: 'General Medicine', doctor: 'Dr. Michael Chen' });
      setShowAdd(false);
      setNotice('Patient saved to the hospital database.');
    } catch (error) {
      setApiState('offline');
      setNotice(error.message || 'Patient was not saved. Check the backend and database connection.');
    }
    window.setTimeout(() => setNotice(''), 5000);
  };
  const handleAuthenticated = (data) => { localStorage.setItem('carepoint_session', JSON.stringify(data)); setSession(data); };
  const signOut = () => { localStorage.removeItem('carepoint_session'); setSession(null); };
  if (!session) return <AuthCenter onAuthenticated={handleAuthenticated} />;
  if (session.role === 'patient') return <PatientPortal session={session} onSignOut={signOut} />;
  if (session.role === 'doctor') return <DoctorPortal session={session} onSignOut={signOut} />;
  return <div className="app-shell">
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><HeartPulse size={23} strokeWidth={2.5}/></div><div><div className="brand-name">carepoint<span>.</span></div><div className="brand-sub">HOSPITAL OS</div></div><button className="sidebar-close" onClick={() => setMobileNav(false)} aria-label="Close menu"><X size={18}/></button></div>
      <div className="facility"><div className="facility-icon"><ShieldCheck size={19}/></div><div className="facility-copy"><strong>CarePoint Medical</strong><span>Main campus · Abuja</span></div><ChevronDown size={15} className="muted"/></div>
      <nav className="nav-list">{navGroups.map(group => <div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(item => <button key={item.name} className={`nav-item ${active === item.name ? 'active' : ''}`} onClick={() => choosePage(item.name)}><item.icon size={18}/><span>{item.name}</span>{
<nav className="nav-list">
  {navGroups.map((group) => (
    <div className="nav-group" key={group.label}>
      <div className="nav-label">{group.label}</div>

      {group.items.map((item) => (
        <button
          key={item.name}
          className={`nav-item ${active === item.name ? 'active' : ''}`}
          onClick={() => choosePage(item.name)}
        >
          <item.icon size={18} />
          <span>{item.name}</span>
        </button>
      ))}
    </div>
  ))}
</nav>
 }</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="support-card"><div className="support-icon"><LifeBuoy size={19}/></div><div><strong>Need a hand?</strong><span>Visit our help center</span></div><ChevronRight size={15}/></div><div className="profile"><div className="profile-avatar">{(session.name || 'U').split(/\s+/).slice(0,2).map(part => part[0]).join('').toUpperCase()}</div><div className="profile-info"><strong>{session.name}</strong><span>{session.role === 'admin' ? 'Hospital administrator' : session.role === 'staff' ? 'Hospital staff' : 'Hospital workspace'}</span></div><MoreHorizontal size={19} className="muted"/></div></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setMobileNav(true)} aria-label="Open navigation"><Menu size={21}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/> <strong>{active}</strong></div></div><div className="topbar-actions"><div className="system-status"><span className={`live-dot ${apiState === 'offline' ? 'offline-dot' : ''}`}/>{apiState === 'connected' ? 'Database connected' : apiState === 'checking' ? 'Checking system' : 'Demo mode · API offline'}</div><button className="icon-button notification-button" aria-label="Notifications" onClick={() => setNotice('You are all caught up on notifications.')}><Bell size={19}/><i/></button><button className="logout-button" onClick={signOut} title="Sign out"><LogOut size={16}/><span>Sign out</span></button><div className="top-avatar">{(session.name || 'Patient').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()}</div></div></header>
      <div className="page-content">
        {active === 'Overview' ? <>
          <div className="page-heading"><div><div className="eyebrow">HOSPITAL OPERATIONS</div><h1>Welcome to CarePoint <span className="wave">✦</span></h1><p>Here’s what’s happening at your hospital today.</p></div><div className="heading-actions"><button className="button button-secondary" onClick={() => setNotice('Report export is ready to be connected to your reporting service.')}><FileText size={16}/> Export report</button><button className="button button-primary" onClick={() => setShowAdd(true)}><Plus size={17}/> Register patient</button></div></div>
          <div className="stats-grid">
            <StatCard title="Total patients" value={patients.length.toLocaleString()} change="—" trend="neutral" note="live records only" icon={Users} tone="blue" chart={[]}/>
            <StatCard title="Appointments today" value={dashboardStats ? String(dashboardStats.activeAppointments ?? 0) : '—'} change="—" trend="neutral" note="active appointments · live API" icon={CalendarDays} tone="purple" chart={[]}/>
            <StatCard title="Available beds" value="—" change="—" trend="neutral" note="bed availability API not connected" icon={BedDouble} tone="teal" chart={[]}/>
            <StatCard title="Revenue this month" value="—" change="—" trend="neutral" note="revenue reporting API not connected" icon={CreditCard} tone="orange" chart={[]}/>
          </div>
          <div className="content-grid"><section className="panel activity-panel"><div className="panel-heading"><div><h2>Patient activity</h2><p>Patient visits over the last 7 days</p></div><button className="select-button" onClick={() => setNotice('Showing patient activity for the last 7 days.')}>Last 7 days <ChevronDown size={14}/></button></div><div className="portal-empty"><Activity size={24}/><strong>No activity report yet</strong><p>Activity charts will appear when verified hospital records are available.</p></div></section>
            <section className="panel appointments-panel"><div className="panel-heading"><div><h2>Today's appointments</h2><p>Upcoming patient visits</p></div><button className="text-link" onClick={() => choosePage('Appointments')}>View all <ChevronRight size={15}/></button></div><div className="appointment-list">{appointments.filter(a => a.date && new Date(a.date).toDateString() === new Date().toDateString()).map((a) => <div className="appointment-row" key={a._id}><div className="time-block"><strong>{new Date(a.date).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</strong><span className="timeline-dot"/></div><div className="mini-avatar teal">{(a.patientName || 'P').split(' ').map(n => n[0]).join('').slice(0,2)}</div><div className="appointment-details"><strong>{a.patientName}</strong><span>{a.department || 'General Medicine'}</span><small>{a.doctor}</small></div><span className={`status status-${String(a.status || 'Scheduled').toLowerCase().replaceAll(' ', '-')}`}>{a.status || 'Scheduled'}</span></div>)}{appointments.filter(a => a.date && new Date(a.date).toDateString() === new Date().toDateString()).length === 0 && <div className="portal-empty"><CalendarDays size={22}/><strong>No appointments scheduled for today</strong><p>Appointments appear here after they are saved through the hospital API.</p></div>}</div><button className="full-width-link" onClick={() => choosePage('Appointments')}>See full schedule <ArrowUpRight size={15}/></button></section></div>
          <section className="panel patients-panel"><div className="panel-heading patient-heading"><div><h2>Recent patients</h2><p>Keep track of the latest patient activity</p></div><div className="patient-tools"><div className="search-box"><Search size={16}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patients..." aria-label="Search patients"/><kbd>⌘ K</kbd></div><button className="button button-secondary button-small" onClick={() => choosePage('Patients')}>View all patients <ChevronRight size={15}/></button></div></div><PatientTable patients={filtered.slice(0, 5)}/><div className="table-footer"><span>Showing <strong>{Math.min(filtered.length, 5)}</strong> of <strong>{patients.length}</strong> patients</span><div className="pagination"><button disabled aria-label="Previous page"><ChevronLeft size={16}/></button><button className="page-current">1</button><button onClick={() => choosePage('Patients')}>2</button><button onClick={() => choosePage('Patients')}>3</button><span>…</span><button onClick={() => choosePage('Patients')}>Next <ChevronRight size={14}/></button></div></div></section>
          <div className="bottom-grid"><section className="panel departments-panel"><div className="panel-heading"><div><h2>Department overview</h2><p>Current capacity across departments</p></div><button className="icon-button subtle" aria-label="Department options"><MoreHorizontal size={19}/></button></div><div className="portal-empty"><BedDouble size={24}/><strong>No department metrics yet</strong><p>Configure departments and connect reporting to show real figures.</p></div></section><section className="panel quick-panel"><div className="panel-heading"><div><h2>Quick actions</h2><p>Common tasks, right at your fingertips</p></div></div><div className="quick-grid"><QuickAction icon={UserRound} title="Add patient" sub="Register a new patient" tone="blue" onClick={() => setShowAdd(true)}/><QuickAction icon={CalendarDays} title="Book appointment" sub="Schedule a patient visit" tone="purple" onClick={() => choosePage('Appointments')}/><QuickAction icon={FileText} title="Create report" sub="Review hospital metrics" tone="teal" onClick={() => choosePage('Reports')}/><QuickAction icon={CreditCard} title="Record payment" sub="Manage patient billing" tone="orange" onClick={() => choosePage('Billing & Payments')}/></div></section></div>
        </> : active === 'Users & Permissions' && session.email?.toLowerCase() === 'setemiadelokun11@gmail.com' ? <OwnerAdminManager session={session} /> : <SectionPage active={active} patients={filtered} appointments={appointments} setAppointments={setAppointments} search={search} setSearch={setSearch} onAdd={() => setShowAdd(true)} onOverview={() => choosePage('Overview')} session={session} />}
        <footer className="footer"><span>© 2026 CarePoint Health Systems</span><span><span className="live-dot"/> Secure healthcare workspace <span className="footer-separator">·</span> v1.0.0</span></footer>
      </div>
    </main>
    {showAdd && <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setShowAdd(false); }}><form className="modal" onSubmit={submitPatient}><div className="modal-head"><div><span className="modal-icon"><UserRound size={19}/></span><h2>Register new patient</h2><p>Add a patient to the CarePoint directory.</p></div><button type="button" className="icon-button" onClick={() => setShowAdd(false)} aria-label="Close dialog"><X size={19}/></button></div><label>Patient full name<input required autoFocus value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="Enter full name"/></label><label>Email address <span className="optional">(optional)</span><input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="Patient email address"/></label><div className="form-row"><label>Department<select value={form.department} onChange={e => setForm({...form, department: e.target.value})}><option>General Medicine</option><option>Cardiology</option><option>Neurology</option><option>Pediatrics</option><option>Orthopedics</option><option>Dermatology</option></select></label><label>Assigned doctor<select value={form.doctor} onChange={e => setForm({...form, doctor: e.target.value})}><option>Dr. Michael Chen</option><option>Dr. Sarah Wilson</option><option>Dr. James Miller</option><option>Dr. Emily Davis</option></select></label></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={() => setShowAdd(false)}>Cancel</button><button type="submit" className="button button-primary"><Plus size={16}/> Register patient</button></div></form></div>}
    {notice && <div className="toast"><CheckCircle2 size={18}/><span>{notice}</span><button onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={15}/></button></div>}
  </div>;
}

function OwnerAdminManager({ session }) {
  const [admins,setAdmins] = useState([]); const [form,setForm] = useState({name:'',email:'',password:''}); const [message,setMessage] = useState(''); const [busy,setBusy] = useState(false);
const api = import.meta.env.VITE_API_URL || '/api';
  const load=async()=>{try{const r=await fetch(`${api}/owner/admins`,{headers:{Authorization:`Bearer ${session.token}`}});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.message||'Could not load administrator accounts.');setAdmins(j.data||[]);}catch(e){setMessage(e.message);}};
  useEffect(()=>{load();},[]);
  const create=async e=>{e.preventDefault();setBusy(true);setMessage('');try{const r=await fetch(`${api}/owner/admins`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.token}`},body:JSON.stringify(form)});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.message||'Could not create administrator.');setForm({name:'',email:'',password:''});setMessage('Administrator account created.');await load();}catch(e){setMessage(e.message);}finally{setBusy(false);}};
  const toggle=async user=>{setMessage('');try{const r=await fetch(`${api}/owner/admins/${user._id}/active`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.token}`},body:JSON.stringify({active:!user.active})});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.message||'Could not update administrator.');await load();}catch(e){setMessage(e.message);}};
  return <div className="section-page"><div className="page-heading section-page-heading"><div><div className="eyebrow">PRIMARY OWNER CONTROL</div><h1>Administrator management</h1><p>Only the owner account can create or deactivate additional administrators.</p></div></div><section className="panel section-list-panel"><div className="panel-heading"><div><h2>Add an administrator</h2><p>Give access only to people you trust. Passwords must be at least 12 characters.</p></div></div><form className="owner-admin-form" onSubmit={create}><label>Full name<input required minLength="2" maxLength="120" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Email address<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Temporary password<input required minLength="12" type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><button className="button button-primary" disabled={busy}>{busy?'Creating…':'Create administrator'}</button></form>{message&&<p className="section-note">{message}</p>}</section><section className="panel section-list-panel"><div className="panel-heading"><div><h2>Administrator accounts</h2><p>Owner email: setemiadelokun11@gmail.com</p></div><button className="button button-secondary" onClick={load}>Refresh</button></div><div className="generic-list">{admins.map(user=><div className="generic-row" key={user._id}><div className="generic-symbol"><ShieldCheck size={17}/></div><div className="generic-main"><strong>{user.name}</strong><span>{user.email}</span><small>{user.email?.toLowerCase()==='setemiadelokun11@gmail.com'?'Primary owner':'Additional administrator'}</small></div><span className="generic-status">{user.active===false?'Inactive':'Active'}</span>{user.email?.toLowerCase()!=='setemiadelokun11@gmail.com'&&<button className="button button-secondary button-small" onClick={()=>toggle(user)}>{user.active===false?'Activate':'Deactivate'}</button>}</div>)}{admins.length===0&&<div className="empty-state"><ShieldCheck size={23}/><strong>No administrator accounts returned</strong><span>Check the API and database connection.</span></div>}</div></section></div>;
}

function PatientPortal({ session, onSignOut }) {
  const firstName = (session.name || 'there').trim().split(/\s+/)[0];
  const [activeTab, setActiveTab] = useState('Overview');
  return <main className="patient-portal"><header className="portal-topbar"><div className="auth-brand"><div className="auth-brand-mark"><HeartPulse size={24}/></div><div><strong>carepoint<span>.</span></strong><small>PATIENT PORTAL</small></div></div><div className="portal-user"><div className="portal-avatar">{(session.name||'P').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()}</div><div><strong>{session.name}</strong><span>{session.email}</span></div><button onClick={onSignOut} className="portal-signout"><LogOut size={16}/><span>Sign out</span></button></div></header><div className="portal-main"><div className="portal-welcome"><div><div className="auth-kicker"><span/> YOUR PERSONAL CARE SPACE</div><h1>Hello, {firstName}.</h1><p>Your health journey, organised in one secure place.</p></div><div className="portal-welcome-art"><HeartPulse size={50}/><span>Care begins with you</span></div></div><nav className="portal-tabs">{['Overview','Appointments','My information'].map(tab=><button key={tab} className={activeTab===tab?'active':''} onClick={()=>setActiveTab(tab)}>{tab}</button>)}</nav>{activeTab==='Overview'?<><div className="portal-cards"><article className="portal-card"><div className="portal-card-icon blue"><CalendarDays size={21}/></div><span>Appointments</span><strong>Plan your next visit</strong><p>View or arrange an appointment with the CarePoint team.</p><button onClick={()=>setActiveTab('Appointments')}>View appointments <ChevronRight size={15}/></button></article><article className="portal-card"><div className="portal-card-icon green"><ShieldCheck size={21}/></div><span>Personal information</span><strong>Your details, in one place</strong><p>Review the account information connected to your portal.</p><button onClick={()=>setActiveTab('My information')}>View my information <ChevronRight size={15}/></button></article><article className="portal-card"><div className="portal-card-icon purple"><HeartPulse size={21}/></div><span>Care support</span><strong>We're here to help</strong><p>Contact the hospital team if you need help with your care.</p><a href="mailto:setemiadelokun11@gmail.com">Contact support <ChevronRight size={15}/></a></article></div><section className="portal-panel"><div className="portal-panel-heading"><div><span>YOUR CARE</span><h2>Welcome to your patient portal</h2></div><span className="portal-status"><i/> Account active</span></div><p>This secure space is ready for your hospital services. Appointment booking, test results, and personal medical records can be connected as those services are enabled by your CarePoint administrator.</p></section></>:activeTab==='Appointments'?<section className="portal-panel"><div className="portal-panel-heading"><div><span>VISIT PLANNING</span><h2>Appointments</h2></div></div><div className="portal-empty"><CalendarDays size={27}/><strong>No appointments to show yet</strong><p>When appointments are linked to your account, they will appear here.</p><button onClick={()=>setActiveTab('Overview')}>Back to overview</button></div></section>:<section className="portal-panel"><div className="portal-panel-heading"><div><span>ACCOUNT DETAILS</span><h2>My information</h2></div></div><div className="portal-info-grid"><div><span>Full name</span><strong>{session.name}</strong></div><div><span>Email address</span><strong>{session.email}</strong></div><div><span>Account type</span><strong>Patient</strong></div><div><span>Security</span><strong className="portal-secure"><ShieldCheck size={15}/> Signed in securely</strong></div></div></section>}<footer className="portal-footer">© 2026 CarePoint Medical <span>Confidential patient access</span></footer></div></main>;
}

function DoctorPortal({ session, onSignOut }) {
  const [tab, setTab] = useState('Overview');
  const [notice, setNotice] = useState('');
  const [appointments, setAppointments] = useState([]);
  const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
  useEffect(() => { fetch(`${api}/appointments`, { headers: { Authorization: `Bearer ${session.token}` } }).then(r => r.ok ? r.json() : Promise.reject()).then(r => setAppointments(r.data || [])).catch(() => setAppointments([])); }, [api, session.token]);
  return <main className="patient-portal"><header className="portal-topbar"><div className="auth-brand"><div className="auth-brand-mark"><Stethoscope size={24}/></div><div><strong>carepoint<span>.</span></strong><small>CLINICIAN WORKSPACE</small></div></div><div className="portal-user"><div className="portal-avatar">{(session.name||'D').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()}</div><div><strong>{session.name}</strong><span>{session.email} · Verified doctor account</span></div><button onClick={onSignOut} className="portal-signout"><LogOut size={16}/> Sign out</button></div></header><div className="portal-main"><div className="portal-welcome"><div><div className="auth-kicker"><span/> CLINICAL WORKSPACE</div><h1>Welcome, Dr. {session.name.replace(/^Dr\.?\s*/i,'')}.</h1><p>Review your schedule and manage assigned patient care.</p></div><div className="portal-welcome-art"><ShieldCheck size={42}/><span>Authenticated clinician access</span></div></div><nav className="portal-tabs">{['Overview','Appointments','Professional profile'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</nav>{tab==='Overview'?<div className="portal-cards"><article className="portal-card"><div className="portal-card-icon blue"><CalendarDays size={21}/></div><span>My schedule</span><strong>{appointments.length} appointments loaded</strong><p>View visits returned by the hospital system for your authenticated account.</p><button onClick={()=>setTab('Appointments')}>Open schedule <ChevronRight size={15}/></button></article><article className="portal-card"><div className="portal-card-icon green"><ShieldCheck size={21}/></div><span>Account security</span><strong>Role-verified access</strong><p>Your account is authenticated by the CarePoint API. Never share your password or token.</p><button onClick={()=>setTab('Professional profile')}>View profile <ChevronRight size={15}/></button></article><article className="portal-card"><div className="portal-card-icon purple"><Users size={21}/></div><span>Patient care</span><strong>Secure clinical workflow</strong><p>Patient records must be accessed only for care purposes and within your assigned permissions.</p><button onClick={()=>setNotice('Use the hospital dashboard to request access to assigned patient records.')}>Access guidance <ChevronRight size={15}/></button></article></div>:tab==='Appointments'?<section className="portal-panel"><div className="portal-panel-heading"><div><span>YOUR SCHEDULE</span><h2>Appointments</h2></div><button className="portal-signout" onClick={()=>setNotice('The appointment list is loaded from the API when records exist.')}>Refresh status</button></div>{appointments.length ? appointments.map((a,i)=><div className="generic-row" key={a._id||i}><div className="generic-symbol"><CalendarDays size={17}/></div><div className="generic-main"><strong>{a.patientName||a.patient?.name||'Patient appointment'}</strong><span>{a.department||'General Medicine'} · {a.date?new Date(a.date).toLocaleString():'Time to be confirmed'}</span></div><span className="generic-status">{a.status||'Scheduled'}</span></div>):<div className="portal-empty"><CalendarDays size={27}/><strong>No appointments assigned yet</strong><p>When the hospital assigns appointments to your account, they will appear here.</p></div>}</section>:<section className="portal-panel"><div className="portal-panel-heading"><div><span>ACCOUNT DETAILS</span><h2>Professional profile</h2></div></div><div className="portal-info-grid"><div><span>Name</span><strong>{session.name}</strong></div><div><span>Work email</span><strong>{session.email}</strong></div><div><span>Account role</span><strong>Doctor</strong></div><div><span>Authentication</span><strong className="portal-secure"><ShieldCheck size={15}/> Verified by CarePoint API</strong></div></div></section>}{notice&&<div className="inline-notice">{notice}<button onClick={()=>setNotice('')}><X size={14}/></button></div>}<footer className="portal-footer">© 2026 CarePoint Medical <span>Confidential clinician access</span></footer></div></main>;
}

function AuthCenter({ onAuthenticated }) {
  const [mode, setMode] = useState('login');
  const [accountType, setAccountType] = useState('patient');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
  async function submit(event) {
    event.preventDefault(); setError(''); setMessage(''); setBusy(true);
    try {
      const endpoint = mode === 'login' ? '/auth/login' : '/auth/register';
      const response = await fetch(`${api}${endpoint}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(mode === 'login' ? { email, password, role: accountType } : { name, email, password }) });
      const result = await response.json();
      if (!response.ok || !result.success) throw new Error(result.message || 'We could not complete your request.');
      if (mode === 'register') { setMode('login'); setPassword(''); setMessage('Account created. Sign in with your email and password.'); }
      else onAuthenticated({ token: result.data.token, name: result.data.user.name, email: result.data.user.email, role: result.data.user.role });
    } catch (err) { setError(err.message || 'Could not connect. Make sure the CarePoint backend is running.'); }
    finally { setBusy(false); }
  }
  return <main className="auth-screen"><div className="auth-glow auth-glow-one"/><div className="auth-glow auth-glow-two"/><div className="auth-top"><div className="auth-brand"><div className="auth-brand-mark"><HeartPulse size={25}/></div><div><strong>carepoint<span>.</span></strong><small>HOSPITAL OS</small></div></div><div className="secure-label"><ShieldCheck size={15}/> Private patient access</div></div><div className="auth-layout"><section className="auth-story"><div className="auth-kicker"><span/> YOUR HEALTH, IN GOOD HANDS</div><h1>Healthcare that<br/><em>puts you first.</em></h1><p>One secure place to connect with your care team, manage appointments, and stay informed about your health journey.</p><div className="auth-feature-list"><div><span className="auth-feature-icon"><CalendarDays size={19}/></span><div><strong>Appointments, made simple</strong><small>Keep your visits organised in one place.</small></div></div><div><span className="auth-feature-icon"><ShieldCheck size={19}/></span><div><strong>Your information stays private</strong><small>Secure access to your personal account.</small></div></div><div><span className="auth-feature-icon"><HeartPulse size={19}/></span><div><strong>Care that stays connected</strong><small>Stay close to the services you need.</small></div></div></div><div className="auth-trust"><div className="trust-pulse"/><span>CarePoint patient portal</span><i/> <span>Available on desktop and mobile</span></div></section><section className="auth-card"><div className="auth-card-heading"><div className="auth-card-symbol"><UserRound size={21}/></div><div><div className="auth-eyebrow">PATIENT PORTAL</div><h2>{mode === 'login' ? 'Welcome back' : 'Create your account'}</h2><p>{mode === 'login' ? 'Sign in to continue to your care space.' : 'A few details to get you started.'}</p></div></div><div className="auth-role-picker"><label htmlFor="accountType">Sign in as</label><select id="accountType" value={accountType} onChange={e=>{setAccountType(e.target.value);if(e.target.value!=='patient')setMode('login');setError('');setMessage('');}}><option value="patient">Patient</option><option value="doctor">Doctor</option><option value="staff">Hospital staff</option><option value="admin">Administrator</option></select><p>Staff and doctor accounts are created by an authorised administrator.</p></div><div className="auth-tabs"><button className={mode === 'login' ? 'selected' : ''} onClick={() => {setMode('login');setError('');setMessage('');}}>Sign in</button>{accountType === 'patient' && <button className={mode === 'register' ? 'selected' : ''} onClick={() => {setMode('register');setError('');setMessage('');}}>Create account</button>}</div><form className="auth-form" onSubmit={submit}>{mode === 'register' && <label>Full name<div className="auth-input-wrap"><UserRound size={17}/><input autoComplete="name" value={name} onChange={e=>setName(e.target.value)} placeholder="Enter your full name" required minLength={2} maxLength={120}/></div></label>}<label>Email address<div className="auth-input-wrap"><span className="at-icon">@</span><input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/></div></label><label>Password<div className="auth-input-wrap"><ShieldCheck size={17}/><input type={showPassword ? 'text' : 'password'} autoComplete={mode === 'login' ? 'current-password' : 'new-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder={mode === 'login' ? 'Enter your password' : 'At least 8 characters'} required minLength={8}/><button className="show-password" type="button" onClick={()=>setShowPassword(v=>!v)}>{showPassword ? 'Hide' : 'Show'}</button></div></label>{error && <div className="auth-alert error"><AlertCircle size={16}/>{error}</div>}{message && <div className="auth-alert success"><CheckCircle2 size={16}/>{message}</div>}<button className="auth-submit" disabled={busy} type="submit">{busy ? 'Please wait…' : mode === 'login' ? 'Sign in securely' : 'Create patient account'}<ChevronRight size={18}/></button></form><div className="auth-card-footer"><ShieldCheck size={15}/><span>Your account is protected by secure authentication.</span></div><div className="auth-support">Need help accessing your account? <a href="mailto:setemiadelokun11@gmail.com">Contact CarePoint support</a><span> · </span><a href="/careers">Apply for a job</a></div></section></div><footer className="auth-footer"><span>© 2026 CarePoint Medical</span><span>Designed for better care <HeartPulse size={13}/></span></footer></main>;
}

function StatCard({ title, value, change, trend, note, icon: Icon, tone, chart }) {
  return <article className="stat-card"><div className="stat-top"><div className={`stat-icon ${tone}`}><Icon size={19}/></div><button className="icon-button stat-more" aria-label={`${title} options`}><MoreHorizontal size={18}/></button></div><div className="stat-title">{title}</div><div className="stat-value">{value}</div><div className="stat-bottom"><span className={`change ${trend === 'neutral' ? 'change-neutral' : ''}`}>{trend === 'up' ? <ArrowUpRight size={14}/> : <ArrowDownRight size={14}/>} {change}</span><span className="stat-note">{note}</span><MiniChart values={chart} tone={tone}/></div></article>;
}
function MiniChart({ values, tone }) { const points = values.map((v, i) => `${i * 9},${32 - v * .29}`).join(' '); return <svg className={`mini-chart ${tone}`} viewBox="0 0 100 34" preserveAspectRatio="none" aria-hidden="true"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>; }
function ActivityChart() { const bars = [{d:'Mon',a:50,b:25},{d:'Tue',a:70,b:36},{d:'Wed',a:59,b:30},{d:'Thu',a:83,b:42},{d:'Fri',a:65,b:34},{d:'Sat',a:92,b:47},{d:'Sun',a:74,b:39}]; return <div className="activity-chart"><div className="chart-y-labels"><span>200</span><span>150</span><span>100</span><span>50</span><span>0</span></div><div className="chart-plot"><div className="chart-gridlines"><i/><i/><i/><i/><i/></div><div className="bar-row">{bars.map(b => <div className="bar-group" key={b.d}><div className="bar-pair"><div className="bar outpatients" style={{height:`${b.a}%`}}/><div className="bar inpatients" style={{height:`${b.b}%`}}/></div><span>{b.d}</span></div>)}</div></div></div>; }
function PatientTable({ patients }) { return <div className="table-scroll"><table className="patient-table"><thead><tr><th><input type="checkbox" aria-label="Select all patients"/></th><th>Patient</th><th>Patient ID</th><th>Department</th><th>Assigned doctor</th><th>Visit date</th><th>Status</th><th/></tr></thead><tbody>{patients.map(p => <tr key={p.id}><td><input type="checkbox" aria-label={`Select ${p.name}`}/></td><td><div className="patient-cell"><div className={`patient-avatar ${p.color}`}>{p.initials}</div><div><strong>{p.name}</strong><span>{p.email}</span></div></div></td><td><span className="patient-id">{p.id}</span></td><td>{p.department}</td><td>{p.doctor}</td><td>{p.date}</td><td><span className={`status status-${p.status.toLowerCase().replaceAll(' ', '-')}`}>{p.status}</span></td><td><button className="row-more" aria-label={`More actions for ${p.name}`}><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table>{patients.length === 0 && <div className="empty-state"><Search size={23}/><strong>No patients found</strong><span>Try a different name, ID, or department.</span></div>}</div>; }
function Department({ name, people, count, value, tone }) { return <div className="department-row"><div className={`department-symbol ${tone}`}><Stethoscope size={17}/></div><div className="department-main"><div className="department-title"><strong>{name}</strong><span>{people}</span></div><div className="progress-track"><div className={`progress-fill ${tone}`} style={{width:`${value}%`}}/></div></div><strong className="department-count">{count}</strong></div>; }
function QuickAction({ icon: Icon, title, sub, tone, onClick }) { return <button className="quick-action" onClick={onClick}><div className={`quick-icon ${tone}`}><Icon size={18}/></div><div><strong>{title}</strong><span>{sub}</span></div><ChevronRight size={16} className="quick-arrow"/></button>; }
function SectionPage({ active, patients, appointments, setAppointments, search, setSearch, onAdd, onOverview, session }) {
  const [doctors, setDoctors] = useState([]);
  const [showDoctorForm, setShowDoctorForm] = useState(false);
  const [doctorForm, setDoctorForm] = useState({ email:'', specialty:'General Practitioner', subspecialty:'', department:'General Medicine', licenseNumber:'', qualifications:'', yearsExperience:'0', consultationFee:'0', availability:'Available' });
  const [filter, setFilter] = useState('All');
  const [localNotice, setLocalNotice] = useState('');
  const [appointmentFilter, setAppointmentFilter] = useState('Today');
  const [showAppointmentForm, setShowAppointmentForm] = useState(false);
  const [appointmentForm, setAppointmentForm] = useState({patientName:'',patientEmail:'',doctor:'',department:'General Medicine',date:'',notes:''});
  useEffect(() => {
    if (active !== 'Doctors & Staff' || !session?.token) return;
    const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
    fetch(`${api}/doctors`, { headers:{ Authorization:`Bearer ${session.token}` } })
      .then(async r => { const body = await r.json(); if (!r.ok) throw new Error(body.message || 'Unable to load doctor profiles.'); return body; })
      .then(body => setDoctors(Array.isArray(body.data) ? body.data : []))
      .catch(error => setLocalNotice(error.message));
  }, [active, session?.token]);
  const saveAppointment = async (event) => { event.preventDefault(); const api=import.meta.env.VITE_API_URL || 'http://localhost:5000/api'; try { const response=await fetch(`${api}/appointments`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.token}`},body:JSON.stringify(appointmentForm)}); const body=await response.json(); if(!response.ok||!body.success) throw new Error(body.message||'Could not create appointment.'); setAppointments(previous=>[...previous,body.data].sort((a,b)=>new Date(a.date)-new Date(b.date))); setAppointmentForm({patientName:'',patientEmail:'',doctor:'',department:'General Medicine',date:'',notes:''}); setShowAppointmentForm(false); setLocalNotice('Appointment saved to the hospital database.'); } catch(error){setLocalNotice(error.message);} };
  const saveDoctorProfile = async (event) => {
    event.preventDefault();
    const api = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
    try {
      const response = await fetch(`${api}/doctors`, { method:'POST', headers:{'Content-Type':'application/json', Authorization:`Bearer ${session.token}`}, body:JSON.stringify({...doctorForm, yearsExperience:Number(doctorForm.yearsExperience), consultationFee:Number(doctorForm.consultationFee)}) });
      const body = await response.json();
      if (!response.ok || !body.success) throw new Error(body.message || 'Could not save doctor profile.');
      setDoctors(previous => [body.data, ...previous.filter(item => item._id !== body.data._id)]);
      setShowDoctorForm(false); setDoctorForm({ email:'', specialty:'General Practitioner', subspecialty:'', department:'General Medicine', licenseNumber:'', qualifications:'', yearsExperience:'0', consultationFee:'0', availability:'Available' });
      setLocalNotice('Doctor specialty profile saved to MongoDB.');
    } catch (error) { setLocalNotice(error.message); }
  };
  const titles = {
    'Patients': ['Patient directory', 'Manage patient profiles, visits, and care assignments.'],
    'Appointments': ['Appointment schedule', 'Review and coordinate upcoming patient visits.'],
    'Doctors & Staff': ['Doctors & staff', 'Your hospital team and department assignments.'],
    'Departments': ['Departments', 'Monitor capacity and services across your hospital.'],
    'Medical Records': ['Medical records', 'Access patient clinical documentation securely.'],
    'Laboratory': ['Laboratory', 'Track laboratory requests and result workflows.'],
    'Pharmacy': ['Pharmacy', 'Manage medication inventory and dispensing activity.'],
    'Billing & Payments': ['Billing & payments', 'Review invoices, patient payments, and balances.'],
    'Reports': ['Reports & analytics', 'Operational insights for informed decisions.'],
    'Settings': ['Workspace settings', 'Manage your hospital workspace preferences.'],
    'Nursing & Vitals': ['Nursing & vital signs', 'Nursing observations, patient monitoring and shift handovers.'],
    'Emergency & OPD': ['Emergency & outpatient care', 'Walk-ins, triage, queues and outpatient visits.'],
    'Radiology & Imaging': ['Radiology & medical imaging', 'Imaging requests, schedules and radiology reports.'],
    'Prescriptions': ['Prescriptions', 'Prescription review, dispensing workflow and medication history.'],
    'Wards & Beds': ['Wards & beds', 'Ward capacity, bed availability and transfers.'],
    'Admissions & Discharges': ['Admissions & discharges', 'Inpatient admission, ward placement and discharge planning.'],
    'Surgery & Theatre': ['Surgery & operating theatre', 'Surgical bookings, theatre schedules and recovery documentation.'],
    'ICU': ['Intensive care unit', 'Critical-care monitoring, observations and care documentation.'],
    'Maternity & Newborn': ['Maternity & newborn care', 'Antenatal visits, delivery records and postnatal care.'],
    'Dental & Physiotherapy': ['Dental & physiotherapy', 'Dental visits, rehabilitation sessions and progress notes.'],
    'Blood Bank': ['Blood bank', 'Donor records, blood inventory and compatibility workflow.'],
    'Ambulance Services': ['Ambulance services', 'Dispatch, crew assignments and patient transfers.'],
    'Insurance Claims': ['Insurance & claims', 'Eligibility, authorizations, claims and insurer follow-up.'],
    'Procurement & Stores': ['Procurement & stores', 'Suppliers, purchase orders and general supplies inventory.'],
    'Maintenance & Equipment': ['Maintenance & equipment', 'Equipment servicing, faults and facilities work orders.'],
    'Staff Schedules': ['Staff schedules', 'Shift planning, availability and department coverage.'],
    'Notifications': ['Notifications & reminders', 'Operational alerts, reminders and read status.'],
    'Medical Documents': ['Medical documents', 'Document requests, attachments and retention workflow.'],
    'Users & Permissions': ['Users & permissions', 'Account provisioning, role assignment and access review.'],
    'Audit Logs': ['Audit logs', 'Review administrative and sensitive record activity.']
  };
  const [title, description] = titles[active] || [active, 'Manage your hospital workspace.'];
  const generic = active !== 'Patients' && active !== 'Appointments';
  const genericRows = {};
  return <><div className="page-heading section-page-heading"><div><div className="eyebrow">CAREPOINT WORKSPACE</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions"><button className="button button-secondary" onClick={onOverview}><LayoutDashboard size={16}/> Overview</button>{active === 'Patients' && <button className="button button-primary" onClick={onAdd}><Plus size={17}/>Register patient</button>}{active === 'Appointments' && ['admin','staff'].includes(session?.role) && <button className="button button-primary" onClick={()=>setShowAppointmentForm(true)}><Plus size={17}/>New appointment</button>}{active === 'Doctors & Staff' && session?.role === 'admin' && <button className="button button-primary" onClick={() => setShowDoctorForm(true)}><Plus size={17}/> Add specialty profile</button>}</div></div>
  <div className="section-stats"><div className="section-stat"><span>Total records</span><strong>{active === 'Patients' ? patients.length.toLocaleString() : active === 'Appointments' ? appointments.length.toLocaleString() : '—'}</strong><small><CheckCircle2 size={13}/> Updated today</small></div><div className="section-stat"><span>Active today</span><strong>{active === 'Patients' ? patients.filter(p => p.status !== 'Completed').length : active === 'Appointments' ? appointments.filter(a => a.status !== 'Completed' && a.status !== 'Cancelled').length : '—'}</strong><small>Across all departments</small></div><div className="section-stat"><span>Needs attention</span><strong>{active === 'Appointments' ? appointments.filter(a => a.status === 'Scheduled').length : '—'}</strong><small><AlertCircle size={13}/> Review recommended</small></div></div>
  <section className="panel section-list-panel"><div className="panel-heading"><div><h2>{active === 'Patients' ? 'All patients' : active === 'Appointments' ? 'Upcoming appointments' : `${active} overview`}</h2><p>Search, review, and manage records in one place.</p></div><div className="patient-tools"><div className="search-box"><Search size={16}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search records..." aria-label="Search records"/></div>{active === 'Patients' && <select className="filter-select" value={filter} onChange={e => setFilter(e.target.value)} aria-label="Filter patient status"><option>All</option><option>Waiting</option><option>Checked in</option><option>Completed</option><option>In consultation</option></select>}{active === 'Appointments' && <select className="filter-select" value={appointmentFilter} onChange={e => setAppointmentFilter(e.target.value)} aria-label="Appointment date filter"><option>Today</option><option>This week</option><option>All upcoming</option></select>}</div></div>
  {active === 'Doctors & Staff' ? <div className="generic-list">{doctors.filter(d => `${d.userId?.name || ''} ${d.userId?.email || ''} ${d.specialty || ''} ${d.department || ''}`.toLowerCase().includes(search.toLowerCase())).map(d => <div className="generic-row doctor-profile-row" key={d._id}><div className="generic-symbol"><Stethoscope size={17}/></div><div className="generic-main"><strong>{d.userId?.name || 'Doctor account'}</strong><span>{d.specialty}{d.subspecialty ? ` · ${d.subspecialty}` : ''} · {d.department}</span><small>{d.userId?.email || ''} · {d.qualifications || 'Qualifications not added'} · {d.yearsExperience || 0} years experience</small></div><span className={`generic-status ${d.availability === 'Available' ? 'doctor-available' : ''}`}>{d.availability}</span></div>)}{doctors.length === 0 && <div className="empty-state"><Stethoscope size={23}/><strong>No saved doctor profiles yet</strong><span>Create a doctor login first, then add their specialty profile.</span></div>}</div> : active === 'Patients' ? <PatientTable patients={patients.filter(p => filter === 'All' || p.status === filter)}/> : active === 'Appointments' ? <div className="simple-appointments">{appointments.filter(a => `${a.patientName || ''} ${a.department || ''} ${a.doctor || ''} ${a.status || ''}`.toLowerCase().includes(search.toLowerCase())).map(a => <div className="simple-appointment" key={a._id}><div className="simple-time"><Clock3 size={16}/>{a.date ? new Date(a.date).toLocaleString() : 'Time not set'}</div><div className="mini-avatar teal">{(a.patientName || 'P').split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div className="appointment-details"><strong>{a.patientName}</strong><span>{a.department || 'General Medicine'}</span><small>{a.doctor}</small></div><span className={`status status-${String(a.status || 'Scheduled').toLowerCase().replaceAll(' ', '-')}`}>{a.status || 'Scheduled'}</span></div>)}{appointments.length===0&&<div className="empty-state"><CalendarDays size={23}/><strong>No appointments found</strong><span>New appointments saved through the API will appear here.</span></div>}</div> : <div className="generic-list">{(genericRows[active] || []).filter(row => row.join(' ').toLowerCase().includes(search.toLowerCase())).map((row,i) => <div className="generic-row" key={`${row[0]}-${i}`}><div className="generic-symbol"><Activity size={17}/></div><div className="generic-main"><strong>{row[0]}</strong><span>{row[1]}</span></div><span className="generic-status">{row[2]}</span></div>)}{!(genericRows[active] || []).length && active !== 'Patients' && active !== 'Appointments' && active !== 'Doctors & Staff' && <div className="empty-state"><Activity size={23}/><strong>No live records available</strong><span>This module must be connected to a validated backend workflow before it can display hospital data.</span></div>}</div>}
  <div className="section-note"><ShieldCheck size={16}/> This module outline is a planning workspace. Connect and verify its API workflow before using it for real patient care.</div></section>
  {showAppointmentForm && <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setShowAppointmentForm(false);}}><form className="modal" onSubmit={saveAppointment}><div className="modal-head"><div><span className="modal-icon"><CalendarDays size={19}/></span><h2>Book appointment</h2><p>Save a real appointment to the hospital database.</p></div><button type="button" className="icon-button" onClick={()=>setShowAppointmentForm(false)} aria-label="Close dialog"><X size={19}/></button></div><label>Patient full name<input required maxLength="120" value={appointmentForm.patientName} onChange={e=>setAppointmentForm({...appointmentForm,patientName:e.target.value})} placeholder="Patient name"/></label><label>Patient email <span className="optional">(optional)</span><input type="email" value={appointmentForm.patientEmail} onChange={e=>setAppointmentForm({...appointmentForm,patientEmail:e.target.value})} placeholder="patient@example.com"/></label><div className="form-row"><label>Doctor / clinician<input required value={appointmentForm.doctor} onChange={e=>setAppointmentForm({...appointmentForm,doctor:e.target.value})} placeholder="Doctor name"/></label><label>Department<input required value={appointmentForm.department} onChange={e=>setAppointmentForm({...appointmentForm,department:e.target.value})} placeholder="Department"/></label></div><label>Date and time<input required type="datetime-local" min={new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)} value={appointmentForm.date} onChange={e=>setAppointmentForm({...appointmentForm,date:e.target.value})}/></label><label>Notes <span className="optional">(optional)</span><textarea maxLength="1000" value={appointmentForm.notes} onChange={e=>setAppointmentForm({...appointmentForm,notes:e.target.value})}/></label><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setShowAppointmentForm(false)}>Cancel</button><button type="submit" className="button button-primary"><Plus size={16}/>Save appointment</button></div></form></div>}
  {showDoctorForm && <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setShowDoctorForm(false); }}><form className="modal doctor-modal" onSubmit={saveDoctorProfile}><div className="modal-head"><div><span className="modal-icon"><Stethoscope size={19}/></span><h2>Add doctor specialty</h2><p>Link an existing doctor login to their professional profile.</p></div><button type="button" className="icon-button" onClick={() => setShowDoctorForm(false)} aria-label="Close dialog"><X size={19}/></button></div><label>Doctor account email<input required type="email" value={doctorForm.email} onChange={e=>setDoctorForm({...doctorForm,email:e.target.value})} placeholder="doctor@hospital.com"/></label><div className="form-row"><label>Medical specialty<select value={doctorForm.specialty} onChange={e=>setDoctorForm({...doctorForm,specialty:e.target.value})}>{['General Practitioner','Family Medicine','Internal Medicine','Cardiology','Neurology','Neurosurgery','Paediatrics','Obstetrics & Gynaecology','General Surgery','Orthopaedic Surgery','Plastic Surgery','Urology','Ophthalmology','Otolaryngology (ENT)','Dermatology','Psychiatry','Psychology','Radiology','Anaesthesiology','Emergency Medicine','Oncology','Pathology','Haematology','Endocrinology','Gastroenterology','Nephrology','Pulmonology','Infectious Diseases','Rheumatology','Dentistry','Oral & Maxillofacial Surgery','Physiotherapy','Other'].map(s=><option key={s}>{s}</option>)}</select></label><label>Department<input required value={doctorForm.department} onChange={e=>setDoctorForm({...doctorForm,department:e.target.value})} placeholder="e.g. Heart Centre"/></label></div><div className="form-row"><label>Subspecialty <span className="optional">(optional)</span><input value={doctorForm.subspecialty} onChange={e=>setDoctorForm({...doctorForm,subspecialty:e.target.value})} placeholder="e.g. Interventional cardiology"/></label><label>Professional licence <span className="optional">(optional)</span><input value={doctorForm.licenseNumber} onChange={e=>setDoctorForm({...doctorForm,licenseNumber:e.target.value})} placeholder="Registration number"/></label></div><label>Qualifications <span className="optional">(optional)</span><input value={doctorForm.qualifications} onChange={e=>setDoctorForm({...doctorForm,qualifications:e.target.value})} placeholder="e.g. MBBS, FWACS"/></label><div className="form-row"><label>Years of experience<input type="number" min="0" max="70" required value={doctorForm.yearsExperience} onChange={e=>setDoctorForm({...doctorForm,yearsExperience:e.target.value})}/></label><label>Consultation fee (₦)<input type="number" min="0" required value={doctorForm.consultationFee} onChange={e=>setDoctorForm({...doctorForm,consultationFee:e.target.value})}/></label></div><label>Availability<select value={doctorForm.availability} onChange={e=>setDoctorForm({...doctorForm,availability:e.target.value})}><option>Available</option><option>Busy</option><option>On leave</option><option>Off duty</option></select></label><div className="section-note"><ShieldCheck size={15}/> Only an existing account with the doctor role can be linked here.</div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setShowDoctorForm(false)}>Cancel</button><button type="submit" className="button button-primary"><Plus size={16}/> Save profile</button></div></form></div>}
  {localNotice && <div className="inline-notice"><CheckCircle2 size={16}/>{localNotice}<button onClick={() => setLocalNotice('')}><X size={14}/></button></div>}
  <div className="section-help"><div className="help-art"><HeartPulse size={24}/></div><div><strong>Need help with {active.toLowerCase()}?</strong><span>Visit the CarePoint help center for workflow guides and best practices.</span></div><button className="text-link" onClick={() => setLocalNotice('Help center connection can be configured by your administrator.')}>Open help center <ArrowUpRight size={15}/></button></div></>;
}
export default App;
